CAT = "plbrKarne"; SEG = "KAR"
# Przestępstwa i wykroczenia związane z bronią: Kodeks karny (t.j. Dz. U. z 2026 r. poz. 1342), art. 50 i 51
# ustawy o broni i amunicji, art. 52 Kodeksu wykroczeń (t.j. Dz. U. z 2026 r. poz. 1372).
Q = [
("Jaka kara grozi za posiadanie broni palnej bez wymaganego zezwolenia?",
 "Od 6 miesięcy do 8 lat więzienia", ["Wyłącznie grzywna w stawkach dziennych", "Areszt do 30 dni", "Pozbawienie wolności do roku, z zawieszeniem"],
 "Art. 263 § 2 Kodeksu karnego: kto bez wymaganego zezwolenia posiada broń palną lub amunicję, podlega karze pozbawienia wolności od 6 miesięcy do lat 8."),
("Za co grozi kara pozbawienia wolności od roku do lat 10 według art. 263 § 1 KK?",
 "Za handel bronią palną bez zezwolenia", ["Za nieumyślną utratę broni palnej", "Za brak legitymacji przy sobie podczas kontroli", "Za przewóz rozładowanej broni w futerale"],
 "Art. 263 § 1 Kodeksu karnego: kto bez wymaganego zezwolenia wyrabia broń palną albo amunicję lub nią handluje, podlega karze pozbawienia wolności od roku do lat 10."),
("Posiadacz pozwolenia daje swój pistolet do potrzymania koledze bez pozwolenia. Jaki czyn z Kodeksu karnego może tu zachodzić?",
 "Udostępnienie broni nieuprawnionemu", ["Handel bronią bez zezwolenia", "Użycie broni w bójce lub pobiciu", "Żaden, jeśli właściciel stał tuż obok"],
 "Art. 263 § 3 Kodeksu karnego: kto, mając zezwolenie na posiadanie broni palnej lub amunicji, udostępnia lub przekazuje ją osobie nieuprawnionej, podlega grzywnie, karze ograniczenia wolności albo pozbawienia wolności do lat 2."),
("Posiadacz zostawił pistolet w toalecie na stacji paliw i broń zginęła. Jaki czyn z Kodeksu karnego dotyczy takiej sytuacji?",
 "Nieumyślna utrata broni palnej", ["Przywłaszczenie cudzej rzeczy ruchomej", "Kradzież z włamaniem", "Żaden, bo broń była jego własnością"],
 "Art. 263 § 4 Kodeksu karnego: kto nieumyślnie powoduje utratę broni palnej lub amunicji, która zgodnie z prawem pozostaje w jego dyspozycji, podlega grzywnie, karze ograniczenia wolności albo pozbawienia wolności do roku."),
("Jaka kara grozi według ustawy o broni i amunicji za porzucenie broni palnej, która pozostaje w czyjejś dyspozycji?",
 "Kara do 2 lat pozbawienia wolności", ["Wyłącznie nagana udzielona przez sąd", "Pozbawienie wolności nie krótsze niż 3 lata", "Tylko cofnięcie pozwolenia, bez kary"],
 "Art. 50 ustawy o broni i amunicji: kto porzuca broń palną lub amunicję, która pozostaje w jego dyspozycji, podlega grzywnie, karze ograniczenia wolności albo pozbawienia wolności do lat 2."),
("Jaki jest charakter czynu osoby, która nosi broń po spożyciu alkoholu?",
 "Wykroczenie z ustawy o broni", ["Czyn dozwolony, jeśli broń jest w kaburze", "Zbrodnia z Kodeksu karnego", "Wyłącznie naruszenie regulaminu strzelnicy"],
 "Art. 51 ust. 2 pkt 4 ustawy o broni i amunicji: karze aresztu albo grzywny podlega, kto nosi broń w stanie po użyciu alkoholu, środka odurzającego, substancji psychotropowych albo środka zastępczego. Organ cofa też pozwolenie (art. 18 ust. 1 pkt 4)."),
("Jaka kara grozi za posiadanie broni pneumatycznej bez wymaganej rejestracji?",
 "Areszt albo grzywna", ["Pozbawienie wolności od 6 miesięcy do lat 8", "Wyłącznie nagana albo upomnienie", "Nie grozi żadna kara ani środek"],
 "Art. 51 ust. 1 ustawy o broni i amunicji: kto bez wymaganej rejestracji posiada broń pneumatyczną, podlega karze aresztu albo grzywny. Jest to wykroczenie, nie przestępstwo z art. 263 KK, który dotyczy broni palnej."),
("Co sąd może orzec obok kary za wykroczenia z art. 51 ust. 1 i 2 ustawy o broni i amunicji?",
 "Przepadek broni i amunicji", ["Wyłącznie zakaz prowadzenia pojazdów", "Przepadek samochodu, którym jechał sprawca", "Nic poza samą grzywną"],
 "Art. 51 ust. 4 ustawy o broni i amunicji: w razie popełnienia wykroczeń z ust. 1 i 2 można orzec przepadek broni i amunicji, chociażby nie stanowiły własności sprawcy."),
("W jakim trybie orzeka się w sprawach o wykroczenia z art. 51 ustawy o broni i amunicji?",
 "Postępowania w sprawach o wykroczenia", ["Postępowania administracyjnego przed komendantem", "Postępowania cywilnego", "Postępowania dyscyplinarnego w klubie"],
 "Art. 51 ust. 5 ustawy o broni i amunicji: orzekanie w sprawach z ust. 1 do 4 następuje w trybie przepisów o postępowaniu w sprawach o wykroczenia."),
("Jaka kara grozi za posiadanie broni bez legitymacji posiadacza broni przy sobie?",
 "Kara grzywny", ["Pozbawienie wolności do lat 2", "Obowiązkowe cofnięcie pozwolenia", "Przepadek broni z mocy prawa"],
 "Art. 51 ust. 3 ustawy o broni i amunicji: kto posiada broń, nie mając przy sobie legitymacji posiadacza broni lub innego dokumentu upoważniającego, podlega karze grzywny."),
("Kto ponosi karę z art. 52 § 1 Kodeksu wykroczeń?",
 "Uczestnik zgromadzenia z bronią", ["Myśliwy w obwodzie łowieckim w czasie polowania", "Strzelec na zawodach sportowych", "Kolekcjoner na wystawie za zgodą Policji"],
 "Art. 52 § 1 Kodeksu wykroczeń: kto bierze udział w zgromadzeniu, posiadając przy sobie broń, materiały wybuchowe, wyroby pirotechniczne lub inne niebezpieczne materiały lub narzędzia, podlega karze aresztu do 14 dni, ograniczenia wolności albo grzywny."),
("Jaki typ czynu zabronionego opisuje art. 159 KK?",
 "Użycie broni palnej w bójce", ["Groźbę karalną z użyciem broni", "Posiadanie broni bez zezwolenia", "Strzelanie na strzelnicy bez prowadzącego"],
 "Art. 159 Kodeksu karnego: kto, biorąc udział w bójce lub pobiciu człowieka, używa broni palnej, noża lub innego podobnie niebezpiecznego przedmiotu, podlega karze pozbawienia wolności od 6 miesięcy do lat 8."),
("Jak KK ocenia rozbój, w którym sprawca posługuje się bronią palną?",
 "Jako rozbój z surowszą karą", ["Jako zwykłą kradzież rzeczy ruchomej", "Jako wykroczenie przeciwko mieniu", "Jako rozbój w typie podstawowym"],
 "Art. 280 § 2 Kodeksu karnego: jeżeli sprawca rozboju posługuje się bronią palną, nożem lub innym podobnie niebezpiecznym przedmiotem, podlega karze pozbawienia wolności od lat 3 do 20 (typ podstawowy z § 1: od lat 2 do 15)."),
("Czynna napaść na policjanta z użyciem broni palnej jest według art. 223 § 1 KK:",
 "Przestępstwem, od roku do 10 lat", ["Wykroczeniem przeciwko porządkowi publicznemu", "Czynem karanym tylko grzywną", "Przestępstwem ściganym z oskarżenia prywatnego"],
 "Art. 223 § 1 Kodeksu karnego: kto, działając wspólnie z inną osobą lub używając broni palnej, noża lub innego podobnie niebezpiecznego przedmiotu albo środka obezwładniającego, dopuszcza się czynnej napaści na funkcjonariusza publicznego, podlega karze od roku do lat 10."),
("Ktoś posiada materiał wybuchowy bez wymaganego zezwolenia. Jaki przepis KK go dotyczy?",
 "Art. 171 § 1 KK", ["Art. 263 § 2 KK", "Art. 51 ust. 1 ustawy o broni i amunicji", "Art. 190 § 1 KK"],
 "Art. 171 § 1 Kodeksu karnego: kto bez wymaganego zezwolenia wyrabia, gromadzi, posiada, posługuje się lub handluje substancją lub przyrządem wybuchowym, podlega karze pozbawienia wolności od 6 miesięcy do lat 8."),
("Podczas czyszczenia broni w domu jej posiadacz nieumyślnie oddaje strzał i zabija domownika. Jakie przestępstwo popełnia?",
 "Nieumyślne spowodowanie śmierci", ["Zabójstwo w typie podstawowym", "Żadne, bo to był nieszczęśliwy wypadek", "Wykroczenie z ustawy o broni i amunicji"],
 "Art. 155 Kodeksu karnego: kto nieumyślnie powoduje śmierć człowieka, podlega karze pozbawienia wolności od 3 miesięcy do lat 5. Nieumyślność to niezachowanie wymaganej ostrożności (art. 9 § 2 KK)."),
("Kiedy w rozumieniu art. 9 § 2 KK czyn popełniony jest nieumyślnie?",
 "Gdy zabrakło wymaganej ostrożności", ["Gdy sprawca chciał go popełnić", "Gdy sprawca był pod wpływem alkoholu", "Gdy czyn popełniono w nocy, bez świadków"],
 "Art. 9 § 2 Kodeksu karnego: czyn jest nieumyślny, jeżeli sprawca, nie mając zamiaru, popełnia go na skutek niezachowania ostrożności wymaganej w danych okolicznościach, mimo że możliwość jego popełnienia przewidywał albo mógł przewidzieć."),
("Myśliwy strzela w zarośla, nie widząc celu, a pocisk przelatuje tuż obok grzybiarza. Jaki czyn z Kodeksu karnego tu zachodzi?",
 "Narażenie na niebezpieczeństwo", ["Udział w bójce lub pobiciu człowieka", "Zniszczenie cudzego mienia", "Żaden, bo nikt nie został ranny"],
 "Art. 160 Kodeksu karnego: kto naraża człowieka na bezpośrednie niebezpieczeństwo utraty życia albo ciężkiego uszczerbku na zdrowiu, podlega karze; przy nieumyślności (§ 3) grzywnie, ograniczeniu wolności albo pozbawieniu wolności do roku."),
("Kto nie podlega karze za narażenie człowieka na niebezpieczeństwo z art. 160 KK?",
 "Kto dobrowolnie uchylił zagrożenie", ["Sprawca z pozwoleniem na broń", "Sprawca, który przeprosił pokrzywdzonego", "Sprawca, który był w pełni trzeźwy"],
 "Art. 160 § 4 Kodeksu karnego: nie podlega karze za przestępstwo z § 1 do 3 sprawca, który dobrowolnie uchylił grożące niebezpieczeństwo."),
("Ktoś widzi rannego po wypadku na strzelnicy i odchodzi, choć mógł bezpiecznie pomóc. Co mu grozi?",
 "Odpowiedzialność za nieudzielenie pomocy", ["Nic, bo nie spowodował wypadku", "Tylko upomnienie przez prowadzącego strzelanie", "Odpowiedzialność za zabójstwo"],
 "Art. 162 § 1 Kodeksu karnego: kto człowiekowi w położeniu grożącym bezpośrednim niebezpieczeństwem utraty życia lub ciężkiego uszczerbku nie udziela pomocy, mogąc jej udzielić bez narażenia siebie lub innej osoby, podlega karze pozbawienia wolności do lat 3."),
("Kiedy według art. 162 § 2 KK nieudzielenie pomocy nie jest przestępstwem?",
 "Gdy zaraz pomoże powołana służba", ["Gdy ranny jest osobą obcą dla świadka", "Gdy świadek bardzo się spieszy", "Gdy ranny sam spowodował wypadek"],
 "Art. 162 § 2 Kodeksu karnego: nie popełnia przestępstwa, kto nie udziela pomocy, do której konieczne jest poddanie się zabiegowi lekarskiemu, albo w warunkach, w których możliwa jest niezwłoczna pomoc ze strony instytucji lub osoby do tego powołanej."),
("Ktoś mierzy z pistoletu do sąsiada i grozi mu zastrzeleniem, a sąsiad poważnie się boi. Jakie przestępstwo popełnia?",
 "Groźbę karalną z Kodeksu karnego", ["Znieważenie innej osoby", "Wykroczenie zakłócenia spokoju", "Żadne, jeśli broń nie była załadowana"],
 "Art. 190 § 1 Kodeksu karnego: kto grozi innej osobie popełnieniem przestępstwa na jej szkodę, jeżeli groźba wzbudza uzasadnioną obawę, że będzie spełniona, podlega karze pozbawienia wolności do lat 3. Ściganie następuje na wniosek pokrzywdzonego (§ 2)."),
("Na czyj wniosek ściga się groźbę karalną z art. 190 KK?",
 "Pokrzywdzonego", ["Prokuratora z urzędu bez wniosku", "Policji", "Organu, który wydał pozwolenie na broń"],
 "Art. 190 § 2 Kodeksu karnego: ściganie groźby karalnej następuje na wniosek pokrzywdzonego."),
("Ktoś nieumyślnie postrzelił drugą osobę, powodując ciężki uszczerbek na zdrowiu. Jaka kara grozi według art. 156 § 2 KK?",
 "Pozbawienie wolności do lat 3", ["Pozbawienie wolności od lat 3 do 20", "Wyłącznie grzywna", "Dożywotnie pozbawienie wolności"],
 "Art. 156 § 2 Kodeksu karnego: jeżeli sprawca ciężkiego uszczerbku na zdrowiu działa nieumyślnie, podlega karze pozbawienia wolności do lat 3. Umyślne spowodowanie takiego uszczerbku grozi karą od lat 3 do 20 (§ 1)."),
]
